// removing photos from a folder needs no code change here — just drop files
// into src/assets/districts/<District Name>/ and rebuild.
// ---------------------------------------------------------------------------

const districtImageModules = import.meta.glob(
  "./assets/districts/*/*.{jpg,jpeg,png,webp,JPG,JPEG,PNG,WEBP}",
  { eager: true, import: "default" }
) as Record<string, string>;

const DISTRICT_IMAGES: Record<string, string[]> = {};
for (const path in districtImageModules) {
  // path looks like "./assets/districts/Agra/1.jpg" — the folder name is
  // the district name exactly as you name the folder.
  const match = path.match(/\.\/assets\/districts\/([^/]+)\//);
  if (!match) continue;
  const districtName = match[1];
  (DISTRICT_IMAGES[districtName] = DISTRICT_IMAGES[districtName] || []).push(
    districtImageModules[path]
  );
}

