// Fits the map to the full-UP bounds exactly once (when the GeoJSON first
// loads), and sets a max pan boundary. Deliberately does NOT re-run on every
// render, so it never fights a district-click zoom afterwards.
function FitUPBounds({ bounds }: { bounds: L.LatLngBounds | null }) {
  const map = useMap();
  const done = useRef(false);
  React.useEffect(() => {
    if (bounds && !done.current) {
      done.current = true;
      map.fitBounds(bounds, { padding: [10, 10] });
      map.setMaxBounds(bounds.pad(0.15));
    }
  }, [bounds, map]);
  return null;
}


// Near-fullscreen photo popup for a district. Images come from
// src/assets/districts/<District Name>/ (see DISTRICT_IMAGES above).
// Layout: 2-column grid, every image in a 4:3 frame, scrolls if there
// are more images than fit on screen.
function DistrictGallery({
  district,
  onClose,
}: {
  district: string;
  onClose: () => void;
}) {
  const images = DISTRICT_IMAGES[district] || [];

  // Close on Escape key
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  return (
    <div
      className="fixed inset-0 z-[2000] bg-black/70 flex items-center justify-center p-3 md:p-6"
      onClick={onClose}
    >
      <div
        className="bg-white rounded-2xl shadow-2xl w-[96vw] h-[94vh] flex flex-col overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-3 border-b border-slate-200 bg-white">
          <div>
            <h3 className="text-lg md:text-xl font-extrabold text-[#0B1F4D]">
              {district}
            </h3>
            <p className="text-xs text-slate-500">
              {images.length} {images.length === 1 ? "photo" : "photos"}
            </p>
          </div>
          <button
            onClick={onClose}
            aria-label="Close gallery"
            className="w-9 h-9 rounded-full bg-slate-100 hover:bg-slate-200 text-slate-700 text-xl leading-none"
          >
            ×
          </button>
        </div>

        {/* Scrollable 2-column grid */}
        <div className="flex-1 overflow-y-auto p-4 md:p-6 bg-slate-50">
          {images.length > 0 ? (
            <div className="grid grid-cols-2 gap-3 md:gap-4">
              {images.map((src, i) => (
                <div
                  key={src}
                  className="aspect-[4/3] w-full overflow-hidden rounded-lg bg-slate-200 shadow"
                >
                  <img
                    src={src}
                    alt={`${district} ${i + 1}`}
                    loading="lazy"
                    className="w-full h-full object-cover"
                  />
                </div>
              ))}
            </div>
          ) : (
            <div className="h-full flex items-center justify-center text-center text-slate-500 text-sm">
              <div>
                <p className="font-bold text-slate-700 mb-1">
                  No photos found for {district}
                </p>
                <p>
                  Add images to{" "}
                  <code className="bg-amber-50 border border-amber-200 rounded px-1.5 py-0.5">
                    src/assets/districts/{district}/
                  </code>{" "}
                  and rebuild.
                </p>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}


function GISMapSection() {
  const [selectedDistrict, setSelectedDistrict] = useState<string | null>(null);
  const [galleryDistrict, setGalleryDistrict] = useState<string | null>(null);
  const [map, setMap] = useState<L.Map | null>(null);
  const [bounds, setBounds] = useState<L.LatLngBounds | null>(null);

  const stadiumsByDistrict = useMemo(() => {
    const map: Record<string, Stadium[]> = {};
    STADIUMS.forEach((s) => {
      (map[s.district] = map[s.district] || []).push(s);
    });
    return map;
  }, []);

  const visibleStadiums = selectedDistrict
    ? stadiumsByDistrict[selectedDistrict] || []
    : [];

  const districtStyle = (feature: any) => {
    const name = feature.properties.district as string;
    const isSelected = name === selectedDistrict;
    const i = Math.abs(hashCode(name)) % PALETTE.length;
    return isSelected
      ? { color: "#0B1F4D", weight: 2.5, fillColor: "#1e3a8a", fillOpacity: 0.65 }
      : { color: "#1e293b", weight: 1, fillColor: PALETTE[i], fillOpacity: 0.55 };
  };

  const onEachDistrict = (feature: any, layer: L.Layer) => {
    const name = feature.properties.district as string;
    layer.bindTooltip(name, {
      permanent: true,
      direction: "center",
      className: "!bg-transparent !border-0 !shadow-none !text-[10px] !font-bold text-slate-800",
    });
    layer.on({
            click: () => {
        setSelectedDistrict(name);
        setGalleryDistrict(name);
        const b = (layer as L.Polygon).getBounds();
        map?.fitBounds(b, { padding: [30, 30], maxZoom: 10 });
      },
      mouseover: () => (layer as L.Path).setStyle({ weight: 2 }),
      mouseout: () => (layer as L.Path).setStyle(districtStyle(feature)),
    });
  };

    const resetView = () => {
    setSelectedDistrict(null);
    setGalleryDistrict(null);
    if (bounds) map?.fitBounds(bounds, { padding: [10, 10] });
  };

  return (
    <section className="relative bg-slate-50 text-slate-900 min-h-screen">
      <div className="sticky top-0 z-30 bg-white border-b border-slate-200 px-6 py-4">
        <h2 className="text-xl font-extrabold text-[#0B1F4D]">
          Uttar Pradesh — District &amp; Stadium Map
        </h2>
        <p className="text-sm text-slate-500">
          View is locked to Uttar Pradesh. Click a district to zoom in and reveal its stadium pins.
        </p>
      </div>

      <div className="relative">
        <MapContainer
          center={[26.85, 80.9]}
          zoom={7}
          minZoom={6}
          maxZoom={11}
          scrollWheelZoom
          zoomControl
          style={{ width: "100%", height: "82vh", minHeight: 520 }}
          ref={setMap}
        >
          {/* Esri light gray canvas — free, no API key, no referrer/CORS
              issues on localhost or file://. Swap for your preferred basemap
              once this is deployed behind a real domain. */}
          <TileLayer
            url="https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Light_Gray_Base/MapServer/tile/{z}/{y}/{x}"
            attribution="Tiles &copy; Esri"
            opacity={0.7}
          />

          <GeoJSON
            data={UP_GEOJSON}
            style={districtStyle}
            onEachFeature={onEachDistrict}
            eventHandlers={{
              add: (e) => setBounds(e.target.getBounds()),
            }}
          />

          <FitUPBounds bounds={bounds} />

                    {visibleStadiums.map((s) => (
            <Marker key={s.name} position={[s.lat, s.lon]} icon={stadiumIcon}>
              <Popup>
                <div className="text-sm">
                  <p className="font-extrabold text-[#0B1F4D]">{s.name}</p>
                  <p className="text-xs text-slate-500">
                    {s.city} · {s.lat.toFixed(4)}, {s.lon.toFixed(4)}
                  </p>
                </div>
              </Popup>
            </Marker>
          ))}
        </MapContainer>

        {/* Legend */}
        <div className="absolute top-[110px] left-4 z-[500] bg-white rounded-xl shadow-lg border border-slate-200 px-3.5 py-3 text-xs max-w-[190px]">
          <h4 className="text-xs font-extrabold text-[#0B1F4D] mb-2">Legend</h4>
          <div className="flex items-center gap-2 mb-1 text-slate-700">
            <span className="w-3 h-3 rounded-sm border border-black/10" style={{ background: "#93c5fd" }} />
            District
          </div>
          <div className="flex items-center gap-2 mb-1 text-slate-700">
            <span className="w-3 h-3 rounded-sm border border-black/10" style={{ background: "#1e3a8a" }} />
            Selected district
          </div>
          <div className="flex items-center gap-2 text-slate-700">
            <span
              className="w-3 h-3 border border-white inline-block"
              style={{ background: "#DC2626", borderRadius: "50% 50% 50% 0", transform: "rotate(-45deg)" }}
            />
            Stadium
          </div>
        </div>

        {/* Info panel */}
        {selectedDistrict && (
          <div className="absolute top-[110px] right-4 z-[500] bg-white rounded-xl shadow-lg border border-slate-200 px-4 py-3.5 text-sm w-[230px]">
            <h3 className="text-[15px] font-extrabold text-[#0B1F4D] mb-0.5">{selectedDistrict}</h3>
            <p className="text-xs text-slate-500 mb-2">
              {visibleStadiums.length} {visibleStadiums.length === 1 ? "stadium" : "stadiums"}
            </p>
            <button
              onClick={resetView}
              className="bg-blue-600 text-white text-xs font-bold px-3 py-1.5 rounded-lg"
            >
              Reset to full UP view
            </button>
          </div>
                )}
      </div>

      {galleryDistrict && (
        <DistrictGallery
          district={galleryDistrict}
          onClose={() => setGalleryDistrict(null)}
        />
      )}
    </section>
  );
}

// ---------------------------------------------------------------------------
// Root export
// ---------------------------------------------------------------------------

export default function UPStadiumAtlas() {
  // No CSS scroll-snap here on purpose: scroll-snap fights GSAP's scrubbed
  // (scroll-position-linked) animations by jumping the scroll position on
  // its own. GSAP's ScrollTrigger is what drives the smoothness now.
  useEffect(() => {
    // Recalculate trigger positions once everything (map, images) has
    // laid out, so scroll offsets stay accurate.
    const id = requestAnimationFrame(() => ScrollTrigger.refresh());
    return () => {
      cancelAnimationFrame(id);
      ScrollTrigger.getAll().forEach((t) => t.kill());
    };
  }, []);

  return (
    <div className="w-full">
      {COVERS.map((c, i) => (
        <CoverSlide key={c.title} index={i} {...c} />
      ))}
      <GISMapSection />
    </div>
  );
}